async process(job: Job<OrderCreatedEvent>): Promise<void> {
  const { orderId, customerEmail, total } = job.data;
  await this.mailer.sendMail({
    to: customerEmail,
    subject: `Order #${orderId} confirmed`,
    text: `We received your order. Total: $${total.toFixed(2)}`,
  });
}

async findById(id: string): Promise<OrderRow | undefined> {
  const rows = await this.dataSource.query(
    'SELECT id, customer_email, total, status FROM orders WHERE id = $1',
    [id],
  );
  return rows[0];
}

async insert(customerEmail: string, total: number, items: OrderItemDto[]): Promise<OrderRow> {
  return this.dataSource.transaction(async (manager) => {
    const [order] = await manager.query(
      'INSERT INTO orders (customer_email, total, status) VALUES ($1, $2, $3) RETURNING id, customer_email, total, status',
      [customerEmail, total, 'created'],
    );
    for (const item of items) {
      await manager.query(
        'INSERT INTO order_items (order_id, sku, quantity, unit_price) VALUES ($1, $2, $3, $4)',
        [order.id, item.sku, item.quantity, item.unitPrice],
      );
    }
    return order;
  });
}

async create(dto: CreateOrderDto) {
  if (dto.items.length === 0) {
    throw new BadRequestException('Order must have at least one item');
  }

  const total = this.calculateTotal(dto.items, dto.couponCode);
  const order = await this.orderRepository.insert(dto.customerEmail, total, dto.items);

  // The email now goes out in the background: the client does not wait for SMTP.
  const event: OrderCreatedEvent = {
    orderId: order.id,
    customerEmail: dto.customerEmail,
    total,
  };
  await this.ordersQueue.add(ORDER_CREATED, event);

  return order;
}

async findById(id: string) {
  const order = await this.orderRepository.findById(id);
  if (!order) {
    throw new NotFoundException(`Order ${id} not found`);
  }
  return order;
}

